/* d0=PC090OJ record index.  Candidate state is helper-derived; mirror remains truth. */

/* d2=byte offset inside the active 0x800-byte PC090OJ mirror. */

/* PC090OJ final teardown: the virtual object-RAM record adapters
 * (.Lpc090oj_emit_slot / .Lpc090oj_clear_slot / .Lpc090oj_mirror_write_word_a1_d0
 * / .Lpc090oj_mirror_write_byte_a1_d0) are REMOVED.  Every former producer has a
 * native Genesis owner (native_frontend_hud_emit, .Lnq_title, status/player-aux
 * lanes, .Lnq_transient_items_emit, .Lnq_gameover_emit); nothing packs an 8-byte
 * PC090OJ record any more.  Proven dead output in Build 0296 (census:
 * docs/design/Andy_pc090oj_final_retirement_census.md). */

/* ------------------------------------------------------------------------- */
/* 17 helpers                                                                */
/* ------------------------------------------------------------------------- */

/* arcade 0x03B902 -- credit-area builder for PC090OJ records 17..21 (credit
 * digits 17/21 + credit-area labels 18..20).
 *
 * Build 0273: RETIRED.  Records 17..21 are now produced natively by
 * native_frontend_hud_emit (credit digit -> native credit block; labels 18..20
 * -> native .Lnq_title_labels set).  All eight callers are frontend HUD-setup
 * paths (arcade 0x3A20E/0x3A264/0x3A640/0x3A6C4/0x3A820/0x3A8E0, plus the now
 * retired 0x3B8B0/0x3B8EE); their records 17..21 are only ever rendered by the
 * frontend object-RAM scan (scene != 1), exactly where native_frontend_hud_emit
 * runs -- gameplay uses the separate .Lnq_gameplay HUD.  So this producer builds
 * no PC090OJ record; every live consumer has a native owner (consumer coverage
 * matrix in the build report).  A bare rts preserves all registers, matching the
 * caller contract. */
genesistan_pc090oj_hook_target_3b902:
    rts

/* RETIRED (setup/priority PC090OJ family).  This helper only PARKED/cleared
 * object-RAM records 5..13.  The producers that formerly populated that HUD
 * band (arcade builders 0x3B8B0 / 0x3B902, generic copier 0x3B930) are retired;
 * verified no live producer writes records 5..13 with content, so the clear
 * services nothing (records stay boot-blank).  Retired to a no-op (preserves
 * all registers). */
genesistan_pc090oj_hook_target_3b926:
    rts

/* PC090OJ final teardown: the Genesis compatibility hook for the generic
 * packed-byte -> object-RAM record copier (arcade 0x03B930) is REMOVED entirely
 * (hook symbol + its remap ownership), not left as an RTS shell.  Arcade 0x3B930
 * is unreachable -- its only callers are inert (0x3B902 body-replaced, 0x3B8B0
 * rts;nop) -- so its original bytes are left as dead, unreachable arcade code. */

/* The old Genesis fallback at these boundaries copied the gameplay player tuple
 * blocks regardless of which arcade producer was replaced.  Main-loop native
 * PLAYER_FRONT/BODY staging retires that player-only compatibility behavior;
 * gameplay keeps the established semantic dispatch/finalize ownership. */
genesistan_pc090oj_hook_target_41dae:
    cmpi.b  #PC090OJ_SCENE_GAMEPLAY_ID, genesistan_current_scene_id
    beq.s   .Lhook_41dae_gameplay_native
    rts
.Lhook_41dae_gameplay_native:
    move.w  0x02A2(%a5), %d0
    cmpi.w  #2, %d0
    beq.s   .Lhook_41dae_mode2
    bsr     native_stage_dispatch_41dae
    bra.s   .Lhook_41dae_finalize
.Lhook_41dae_mode2:
    bsr     native_stage_dispatch_45dfa
.Lhook_41dae_finalize:
    bsr     pc090oj_native_emit_pass
    rts

genesistan_pc090oj_hook_target_41f5e:
    cmpi.b  #PC090OJ_SCENE_GAMEPLAY_ID, genesistan_current_scene_id
    beq.s   .Lhook_41f5e_gameplay_native
    rts
.Lhook_41f5e_gameplay_native:
    bsr     native_sprite_frame_begin
    rts

genesistan_pc090oj_hook_target_45dfa:
    cmpi.b  #PC090OJ_SCENE_GAMEPLAY_ID, genesistan_current_scene_id
    beq.s   .Lhook_45dfa_gameplay_native
    rts
.Lhook_45dfa_gameplay_native:
    bsr     native_stage_dispatch_45dfa
    bsr     pc090oj_native_emit_pass
    rts


/* Build 0250 native gameplay sprite lanes.  These queues are semantic output
 * lanes, not PC090OJ object RAM: producers append visible 16x16 pieces and the
 * finalizer later concatenates them into one Genesis SAT chain.  Legacy mirror
 * code remains physically present for frontend/non-gameplay comparison only. */
native_sprite_frame_begin:
    /* arcade 0x5A098 publishes the persistent gameplay energy/status lane
     * before this frame boundary.  It owns refresh/retention of that lane;
     * clearing it here would discard the native status output before the
     * gameplay finalizer can consume it. */
    clr.w   native_front_effect_count
    clr.w   native_middle_count
    clr.w   native_back_enemy_count
    clr.w   pc090oj_sat_frame_ready
    rts

/* Main-loop player producers own these two completed semantic lanes.  Reset
 * once before arcade 0x51060 (FRONT), then BODY appends later at 0x5151C. */
native_player_frame_begin:
    clr.w   native_player_front_count
    clr.w   native_player_body_count
    rts

native_player_front_begin:
    move.w  #NATIVE_LANE_PLAYER_FRONT, native_sprite_lane
    rts

native_player_body_begin:
    move.w  #NATIVE_LANE_PLAYER_BODY, native_sprite_lane
    rts

/* Retained arcade expanders provide d1=word0, d6=Y, d3=code and d4=X.
 * Preserve their d2 loop counter while adapting to native_sprite_emit. */
native_player_piece:
    move.w  %d2, -(%sp)
    move.w  %d6, %d2
    bsr     native_sprite_emit
    move.w  (%sp)+, %d2
    rts

/* The old Block-A tuple-0 consumer copied this anchor into player state after
 * BODY generation.  Tuple 0 is the first iteration of the 0x545BA expander;
 * publish the same semantic coordinates directly without retaining Block A. */
native_player_body_anchor_piece:
    cmpi.w  #4, %d2
    bne.s   .Lnative_player_anchor_emit
    move.w  %d4, 0x129A(%a5)
    move.w  %d6, 0x129C(%a5)
.Lnative_player_anchor_emit:
    bra     native_player_piece

native_player_body_anchor_blank:
    cmpi.w  #4, %d2
    bne.s   .Lnative_player_anchor_blank_done
    clr.w   0x129A(%a5)
    clr.w   0x129C(%a5)
.Lnative_player_anchor_blank_done:
    rts

native_player_body_anchor_clear:
    clr.w   0x129A(%a5)
    clr.w   0x129C(%a5)
    rts

/* d1=word0/attr nibble+flip bits, d2=PC090OJ Y word, d3=source artwork code,
 * d4=PC090OJ X word, native_sprite_lane selects queue.  Preserves all caller
 * registers.  Hidden/blank/code-zero pieces append nothing.  All lanes retain
 * the producer's arcade-semantic Y; the shared visible-origin conversion is
 * applied once when the final SAT entry is encoded. */
native_sprite_emit:
    movem.l %d0-%d7/%a0-%a2, -(%sp)
    move.w  %d3, %d0
    andi.w  #0x1FFF, %d0
    beq     .Lnse_done
    cmpi.w  #0x00FF, %d0
    beq     .Lnse_done
    move.w  %d2, %d0
    andi.w  #0x01FF, %d0
    cmpi.w  #0x0180, %d0
    beq     .Lnse_done

    move.w  native_sprite_lane, %d0
    cmpi.w  #NATIVE_LANE_HUD, %d0
    beq.s   .Lnse_hud
    cmpi.w  #NATIVE_LANE_FRONT_EFFECT, %d0
    beq.s   .Lnse_front_effect
    cmpi.w  #NATIVE_LANE_PLAYER_FRONT, %d0
    beq.s   .Lnse_player_front
    cmpi.w  #NATIVE_LANE_MIDDLE, %d0
    beq.s   .Lnse_middle
    cmpi.w  #NATIVE_LANE_PLAYER_BODY, %d0
    beq.s   .Lnse_player_body
    cmpi.w  #NATIVE_LANE_BACK_ENEMY, %d0
    beq.s   .Lnse_back_enemy
    bra     .Lnse_done
.Lnse_hud:
    lea     native_queue_hud, %a0
    lea     native_hud_count, %a1
    move.w  #NATIVE_HUD_BOUND, %d5
    bra.s   .Lnse_store
.Lnse_front_effect:
    lea     native_queue_front_effect, %a0
    lea     native_front_effect_count, %a1
    move.w  #NATIVE_FRONT_EFFECT_BOUND, %d5
    bra.s   .Lnse_store
.Lnse_player_front:
    lea     native_queue_player_front, %a0
    lea     native_player_front_count, %a1
    move.w  #NATIVE_PLAYER_FRONT_BOUND, %d5
    bra.s   .Lnse_store
.Lnse_middle:
    lea     native_queue_middle, %a0
    lea     native_middle_count, %a1
    move.w  #NATIVE_MIDDLE_BOUND, %d5
    bra.s   .Lnse_store
.Lnse_player_body:
    lea     native_queue_player_body, %a0
    lea     native_player_body_count, %a1
    move.w  #NATIVE_PLAYER_BODY_BOUND, %d5
    bra.s   .Lnse_store
.Lnse_back_enemy:
    lea     native_queue_back_enemy, %a0
    lea     native_back_enemy_count, %a1
    move.w  #NATIVE_BACK_ENEMY_BOUND, %d5
.Lnse_store:
    move.w  (%a1), %d0
    cmp.w   %d5, %d0
    bhs.s   .Lnse_done
    move.w  %d0, %d6
    lsl.w   #3, %d6
    adda.w  %d6, %a0
    move.w  %d1, (%a0)+
    move.w  %d2, (%a0)+
    move.w  %d3, (%a0)+
    move.w  %d4, (%a0)+
    addq.w  #1, (%a1)
.Lnse_done:
    movem.l (%sp)+, %d0-%d7/%a0-%a2
    rts

native_stage_dispatch_41dae:
    movem.l %d0-%d7/%a0-%a6, -(%sp)
    move.w  #NATIVE_LANE_PLAYER_FRONT, native_sprite_lane
    lea     0x0508(%a5), %a4
    lea     0x00D001C8, %a1
    moveq   #(2 - 1), %d5
.Lns41_players1:
    moveq   #13, %d2
    bsr     .Lnative_emit_actor_common
    adda.w  #64, %a4
    dbra    %d5, .Lns41_players1

    move.w  #NATIVE_LANE_MIDDLE, native_sprite_lane
    lea     0x05C8(%a5), %a4
